<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Donation; use App\Models\Expense; use Illuminate\Http\Request;
class ReportExportController extends Controller { public function donationsCsv(Request $r){$rows=Donation::where('status','completed')->latest()->get(['id','name','email','amount','currency','payment_method','status','created_at']);$file='donations-'.now()->format('Ymd-His').'.csv';$headers=['Content-Type'=>'text/csv','Content-Disposition'=>'attachment; filename="'.$file.'"'];return response()->streamDownload(function()use($rows){$out=fopen('php://output','w');fputcsv($out,['ID','Name','Email','Amount','Currency','Method','Status','Date']);foreach($rows as $x)fputcsv($out,$x->toArray());fclose($out);},$file,$headers);} public function expensesCsv(){ $rows=Expense::latest()->get(['id','category','amount','expense_date','description']);$file='expenses-'.now()->format('Ymd-His').'.csv';return response()->streamDownload(function()use($rows){$o=fopen('php://output','w');fputcsv($o,['ID','Category','Amount','Date','Description']);foreach($rows as $x)fputcsv($o,$x->toArray());fclose($o);},$file,['Content-Type'=>'text/csv']);} }
